arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg: oklch(0.99 0.01 160);
+  --surface: oklch(1 0 0);
+  --surface-2: oklch(0.985 0.01 165);
+  --text: oklch(0.17 0.02 250);
+  --muted: oklch(0.52 0.02 240);
+  --border: oklch(0.90 0.01 220);
+
+  --teal-1: oklch(0.975 0.03 190);
+  --teal-2: oklch(0.93 0.06 190);
+  --teal-3: oklch(0.80 0.11 190);
+  --teal-4: oklch(0.62 0.12 190);
+  --teal-5: oklch(0.52 0.12 190);
+
+  --accent: oklch(0.74 0.16 35);
+  --accent-2: oklch(0.80 0.14 85);
+
+  --shadow-sm: 0 1px 0 rgba(0,0,0,.04), 0 8px 22px rgba(2, 20, 24, .08);
+  --shadow-md: 0 1px 0 rgba(0,0,0,.05), 0 16px 40px rgba(2, 20, 24, .12);
+  --radius: 16px;
+  --radius-sm: 12px;
+  --ring: 0 0 0 4px color-mix(in oklab, oklch(0.62 0.12 190) 28%, transparent);
+  --font-sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Inter, "DM Sans", Arial, "Apple Color Emoji", "Segoe UI Emoji";
+}
+
+*{box-sizing:border-box}
+html{scroll-behavior:smooth}
+body{
+  margin:0;
+  font-family: var(--font-sans);
+  background: radial-gradient(900px 500px at 10% -10%, color-mix(in oklab, var(--teal-2) 55%, white) 0%, transparent 60%),
+              radial-gradient(700px 380px at 95% 0%, color-mix(in oklab, var(--accent-2) 36%, white) 0%, transparent 55%),
+              var(--bg);
+  color: var(--text);
+}
+
+a{color:inherit; text-decoration:none}
+a:hover{text-decoration:underline}
+
+.container{max-width:1180px; margin:0 auto; padding:0 20px}
+
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); border:0}
+
+.pill{
+  display:inline-flex; align-items:center; gap:.45rem;
+  border:1px solid var(--border);
+  background: color-mix(in oklab, var(--surface) 88%, var(--teal-1));
+  padding:.35rem .65rem;
+  border-radius:999px;
+  color: color-mix(in oklab, var(--text) 78%, var(--teal-5));
+  font-size:.85rem;
+}
+
+.btn{
+  display:inline-flex; align-items:center; justify-content:center; gap:.55rem;
+  border-radius:999px;
+  padding:.72rem 1.0rem;
+  border:1px solid transparent;
+  cursor:pointer;
+  font-weight:650;
+  letter-spacing:.1px;
+  transition: transform 140ms ease, box-shadow 180ms ease, background 180ms ease, border-color 180ms ease;
+  user-select:none;
+}
+.btn:active{transform:scale(.98)}
+.btn-primary{
+  background: linear-gradient(180deg, color-mix(in oklab, var(--teal-4) 92%, white), var(--teal-5));
+  color:white;
+  box-shadow: var(--shadow-sm);
+}
+.btn-primary:hover{box-shadow: var(--shadow-md); text-decoration:none}
+.btn-secondary{
+  background: color-mix(in oklab, var(--surface) 86%, var(--teal-1));
+  border-color: color-mix(in oklab, var(--border) 82%, var(--teal-2));
+  color: color-mix(in oklab, var(--text) 90%, var(--teal-5));
+}
+.btn-secondary:hover{box-shadow: var(--shadow-sm); text-decoration:none}
+.btn-accent{
+  background: linear-gradient(180deg, color-mix(in oklab, var(--accent) 88%, white), color-mix(in oklab, var(--accent) 78%, black));
+  color: oklch(0.98 0 0);
+  box-shadow: var(--shadow-sm);
+}
+
+.card{
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  border: 1px solid color-mix(in oklab, var(--border) 86%, white);
+  border-radius: var(--radius);
+  box-shadow: 0 1px 0 rgba(0,0,0,.03);
+}
+.card:hover{box-shadow: var(--shadow-sm)}
+
+.focus-ring:focus-visible{outline:none; box-shadow: var(--ring)}
+
+/* Header */
+.topbar{
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  backdrop-filter: blur(10px);
+  border-bottom: 1px solid color-mix(in oklab, var(--border) 75%, white);
+}
+.topbar-inner{display:flex; align-items:center; justify-content:space-between; gap:16px; padding:14px 0}
+.brand{display:flex; align-items:center; gap:12px}
+.brand-mark{
+  width:40px; height:40px; border-radius:12px;
+  background: radial-gradient(14px 14px at 30% 32%, rgba(255,255,255,.9) 0%, rgba(255,255,255,0) 60%),
+              linear-gradient(180deg, color-mix(in oklab, var(--teal-4) 85%, white), var(--teal-5));
+  box-shadow: 0 1px 0 rgba(0,0,0,.03), 0 10px 25px rgba(0, 131, 141, .18);
+}
+.brand-name{font-weight:800; letter-spacing:-.3px; font-size:1.05rem}
+.brand-sub{font-size:.78rem; color:var(--muted); margin-top:2px}
+
+.nav{display:flex; align-items:center; gap:6px}
+.nav-btn{
+  border:1px solid transparent;
+  background: transparent;
+  padding:10px 10px;
+  border-radius:999px;
+  font-weight:650;
+  color: color-mix(in oklab, var(--text) 90%, var(--teal-5));
+  cursor:pointer;
+  transition: background 160ms ease, border-color 160ms ease;
+}
+.nav-btn:hover{background: color-mix(in oklab, var(--teal-1) 55%, white)}
+.nav-btn[aria-expanded="true"]{background: color-mix(in oklab, var(--teal-1) 75%, white); border-color: color-mix(in oklab, var(--border) 78%, var(--teal-2))}
+
+.actions{display:flex; align-items:center; gap:10px}
+.link{
+  font-weight:650;
+  color: color-mix(in oklab, var(--text) 85%, var(--teal-5));
+  padding:10px 10px;
+  border-radius:999px;
+}
+.link:hover{background: color-mix(in oklab, var(--teal-1) 55%, white); text-decoration:none}
+
+.menu-overlay{display:none; position:fixed; inset:0; background: rgba(6, 26, 30, .16); z-index:40}
+.menu-overlay[data-open="true"]{display:block}
+
+.mega{
+  position: absolute;
+  left: 50%;
+  transform: translateX(-50%);
+  top: 72px;
+  width: min(1180px, calc(100vw - 24px));
+  display: none;
+  border-radius: 20px;
+  box-shadow: var(--shadow-md);
+  border: 1px solid color-mix(in oklab, var(--border) 70%, white);
+  overflow: hidden;
+}
+.mega[data-open="true"]{display:block; animation: fadeDown 180ms ease-out}
+@keyframes fadeDown{from{opacity:0; transform: translateX(-50%) translateY(-8px)} to{opacity:1; transform: translateX(-50%) translateY(0)}}
+
+.mega-inner{display:grid; grid-template-columns: 1.2fr .8fr; gap:0; background: var(--surface)}
+.mega-left{padding:18px 18px 20px 18px}
+.mega-right{
+  padding:18px;
+  background: linear-gradient(180deg, color-mix(in oklab, var(--teal-1) 65%, white), color-mix(in oklab, var(--surface) 80%, var(--teal-1)));
+  border-left: 1px solid color-mix(in oklab, var(--border) 75%, white);
+}
+.mega-title{font-weight:800; font-size:1.02rem; letter-spacing:-.2px}
+.mega-desc{margin-top:4px; color:var(--muted); font-size:.92rem; line-height:1.35}
+.mega-grid{margin-top:14px; display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap:10px}
+.mega-link{
+  display:flex; align-items:center; justify-content:space-between;
+  padding:10px 12px;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklab, var(--border) 80%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  transition: transform 140ms ease, box-shadow 180ms ease, border-color 180ms ease;
+}
+.mega-link:hover{transform: translateY(-1px); box-shadow: 0 14px 30px rgba(2, 20, 24, .10); border-color: color-mix(in oklab, var(--border) 72%, var(--teal-2)); text-decoration:none}
+.mega-link span{font-weight:650}
+.mega-link small{color:var(--muted); font-weight:600}
+
+.mega-feature{
+  border-radius: 18px;
+  padding: 14px;
+  border: 1px solid color-mix(in oklab, var(--border) 70%, white);
+  background: radial-gradient(500px 260px at 30% 10%, color-mix(in oklab, var(--teal-2) 60%, white) 0%, transparent 55%),
+              linear-gradient(180deg, color-mix(in oklab, var(--surface) 90%, white), color-mix(in oklab, var(--teal-1) 52%, white));
+}
+.mega-feature h4{margin:0; font-size:0.95rem; font-weight:850; letter-spacing:-.2px}
+.mega-feature p{margin:6px 0 0 0; color:var(--muted); font-size:.9rem; line-height:1.35}
+.mega-feature .cta{margin-top:12px}
+
+/* Credibility ticker */
+.ticker-wrap{
+  border-top: 1px solid color-mix(in oklab, var(--border) 75%, white);
+  border-bottom: 1px solid color-mix(in oklab, var(--border) 75%, white);
+  background: linear-gradient(180deg, color-mix(in oklab, var(--surface) 92%, white), color-mix(in oklab, var(--teal-1) 50%, white));
+}
+.ticker{
+  display:flex;
+  gap: 18px;
+  align-items:center;
+  overflow:hidden;
+  padding: 10px 0;
+}
+.ticker-track{
+  display:flex;
+  gap: 14px;
+  align-items:center;
+  white-space: nowrap;
+  animation: ticker 22s linear infinite;
+}
+.ticker:hover .ticker-track{animation-play-state: paused}
+@keyframes ticker{from{transform: translateX(0)} to{transform: translateX(-50%)}}
+.stat{
+  display:inline-flex; align-items:center; gap:.5rem;
+  padding:.45rem .75rem;
+  border-radius:999px;
+  background: color-mix(in oklab, var(--surface) 88%, white);
+  border: 1px solid color-mix(in oklab, var(--border) 82%, white);
+  box-shadow: 0 1px 0 rgba(0,0,0,.02);
+  font-weight:750;
+  color: color-mix(in oklab, var(--text) 86%, var(--teal-5));
+}
+.stat i{width:16px; height:16px; display:inline-block}
+
+/* Sections */
+main{padding-bottom: 60px}
+.section{padding: 38px 0}
+.section-title{display:flex; align-items:flex-end; justify-content:space-between; gap:16px}
+.section-title h2{margin:0; font-size:1.35rem; letter-spacing:-.4px}
+.section-title p{margin:8px 0 0 0; color:var(--muted); max-width: 62ch; line-height:1.45}
+.section-link{color: color-mix(in oklab, var(--teal-5) 78%, var(--text)); font-weight:700}
+
+/* Hero */
+.hero{padding: 30px 0 18px}
+.hero-grid{display:grid; grid-template-columns: 1.2fr .8fr; gap: 18px; align-items:stretch}
+.hero-card{padding: 22px; border-radius: 24px; box-shadow: var(--shadow-sm)}
+.hero-card:hover{box-shadow: var(--shadow-md)}
+.hero-kicker{display:flex; align-items:center; justify-content:space-between; gap:10px}
+.badge{
+  display:inline-flex; align-items:center; gap:.5rem;
+  padding:.45rem .65rem;
+  border-radius: 999px;
+  border: 1px solid color-mix(in oklab, var(--border) 78%, var(--teal-2));
+  background: radial-gradient(250px 120px at 30% 10%, rgba(255,255,255,.95) 0%, transparent 55%),
+              linear-gradient(180deg, color-mix(in oklab, var(--teal-2) 58%, white), color-mix(in oklab, var(--surface) 80%, var(--teal-1)));
+  font-weight:800;
+  color: color-mix(in oklab, var(--text) 75%, var(--teal-5));
+}
+.hero h1{margin:14px 0 0 0; font-size:2.15rem; line-height:1.08; letter-spacing:-.9px}
+.hero p{margin:12px 0 0 0; color:var(--muted); font-size:1.02rem; line-height:1.55}
+.hero-cta{margin-top:18px; display:flex; gap:10px; flex-wrap:wrap}
+.hero-meta{margin-top:16px; display:flex; gap:10px; flex-wrap:wrap}
+.meta{
+  display:flex; align-items:center; gap:.55rem;
+  padding:.55rem .75rem;
+  border-radius: 14px;
+  border: 1px solid color-mix(in oklab, var(--border) 80%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  color: color-mix(in oklab, var(--text) 82%, var(--teal-5));
+  font-weight:700;
+  font-size:.92rem;
+}
+.meta svg{width:18px; height:18px}
+
+.hero-aside{padding: 18px; border-radius: 24px}
+.hero-aside h3{margin:0; font-size:1.05rem; letter-spacing:-.25px}
+.hero-aside .desc{margin:8px 0 0 0; color:var(--muted); line-height:1.45}
+.hero-aside .search{margin-top:12px; display:flex; gap:10px}
+.input{
+  width: 100%;
+  padding: .85rem .95rem;
+  border-radius: 14px;
+  border:1px solid color-mix(in oklab, var(--border) 80%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  font-size: 0.98rem;
+  outline:none;
+  transition: box-shadow 180ms ease, border-color 180ms ease;
+}
+.input:focus{border-color: color-mix(in oklab, var(--teal-4) 55%, var(--border)); box-shadow: var(--ring)}
+
+/* Trending */
+.trending-grid{display:grid; grid-template-columns: 1.2fr .8fr; gap: 18px; align-items:start}
+.feature-media{
+  border-radius: 20px;
+  overflow:hidden;
+  border: 1px solid color-mix(in oklab, var(--border) 75%, white);
+  background: radial-gradient(600px 320px at 20% 20%, color-mix(in oklab, var(--teal-2) 64%, white) 0%, transparent 60%),
+              radial-gradient(500px 300px at 90% 10%, color-mix(in oklab, var(--accent-2) 40%, white) 0%, transparent 55%),
+              linear-gradient(180deg, color-mix(in oklab, var(--surface) 90%, white), color-mix(in oklab, var(--surface-2) 75%, var(--teal-1)));
+  min-height: 310px;
+  display:flex;
+  padding: 18px;
+}
+.feature-media-inner{margin-top:auto; max-width: 60ch}
+.feature-media h3{margin:0; font-size:1.28rem; letter-spacing:-.4px}
+.feature-media p{margin:8px 0 0 0; color:var(--muted); line-height:1.5}
+
+.list{padding: 16px}
+.list h3{margin:0 0 10px 0; font-size:1.05rem; letter-spacing:-.25px}
+.trend-item{display:flex; gap:10px; padding: 10px 10px; border-radius: 14px; border:1px solid transparent}
+.trend-item:hover{background: color-mix(in oklab, var(--teal-1) 55%, white); border-color: color-mix(in oklab, var(--border) 78%, var(--teal-2)); text-decoration:none}
+.trend-label{font-size:.74rem; font-weight:850; letter-spacing:.08em; text-transform:uppercase; color: color-mix(in oklab, var(--teal-5) 85%, var(--text));}
+.trend-title{font-weight:750; margin-top:3px}
+
+/* Newsletter CTA */
+.cta{
+  border-radius: 26px;
+  overflow:hidden;
+  box-shadow: var(--shadow-md);
+  border: 1px solid color-mix(in oklab, var(--border) 70%, white);
+  background: radial-gradient(700px 380px at 10% 0%, color-mix(in oklab, var(--teal-2) 70%, white) 0%, transparent 60%),
+              radial-gradient(560px 360px at 95% 20%, color-mix(in oklab, var(--accent-2) 40%, white) 0%, transparent 55%),
+              linear-gradient(180deg, color-mix(in oklab, var(--surface) 85%, white), color-mix(in oklab, var(--surface-2) 85%, var(--teal-1)));
+}
+.cta-inner{display:grid; grid-template-columns: 1.1fr .9fr; gap: 18px; padding: 22px}
+.cta h2{margin:0; font-size:1.45rem; letter-spacing:-.5px}
+.cta p{margin:10px 0 0 0; color:var(--muted); line-height:1.55}
+.cta form{display:flex; gap:10px; align-items:center}
+.hint{margin-top:10px; color:var(--muted); font-size:.9rem}
+
+/* Topics carousel */
+.carousel{
+  position: relative;
+}
+.carousel-viewport{
+  overflow:hidden;
+  border-radius: 22px;
+  border:1px solid color-mix(in oklab, var(--border) 76%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+}
+.carousel-track{
+  display:flex;
+  gap: 14px;
+  padding: 16px;
+  scroll-behavior:smooth;
+  overflow-x:auto;
+  scrollbar-width: none;
+}
+.carousel-track::-webkit-scrollbar{display:none}
+.topic{
+  min-width: 172px;
+  border-radius: 20px;
+  border: 1px solid color-mix(in oklab, var(--border) 80%, white);
+  background: linear-gradient(180deg, color-mix(in oklab, var(--surface) 92%, white), color-mix(in oklab, var(--teal-1) 45%, white));
+  padding: 14px;
+  transition: transform 160ms ease, box-shadow 180ms ease;
+}
+.topic:hover{transform: translateY(-2px); box-shadow: var(--shadow-sm); text-decoration:none}
+.topic .img{
+  width: 86px; height: 86px;
+  border-radius: 999px;
+  border: 1px solid color-mix(in oklab, var(--border) 78%, white);
+  background: radial-gradient(14px 14px at 30% 30%, rgba(255,255,255,.95) 0%, rgba(255,255,255,0) 60%),
+              linear-gradient(180deg, color-mix(in oklab, var(--teal-2) 55%, white), color-mix(in oklab, var(--surface) 75%, var(--teal-1)));
+  display:flex; align-items:center; justify-content:center;
+  box-shadow: 0 1px 0 rgba(0,0,0,.03);
+}
+.topic .img svg{width:34px; height:34px; color: color-mix(in oklab, var(--teal-5) 86%, var(--text))}
+.topic h4{margin:12px 0 0 0; font-size:1.0rem; letter-spacing:-.25px}
+.topic p{margin:6px 0 0 0; color:var(--muted); font-size:.9rem; line-height:1.35}
+
+.car-btn{
+  position:absolute;
+  top: 50%;
+  transform: translateY(-50%);
+  width: 44px; height: 44px;
+  border-radius: 999px;
+  border:1px solid color-mix(in oklab, var(--border) 76%, white);
+  background: color-mix(in oklab, var(--surface) 90%, white);
+  box-shadow: 0 10px 25px rgba(2,20,24,.12);
+  display:flex; align-items:center; justify-content:center;
+  cursor:pointer;
+  transition: transform 140ms ease, box-shadow 180ms ease;
+}
+.car-btn:hover{box-shadow: var(--shadow-md)}
+.car-btn:active{transform: translateY(-50%) scale(.98)}
+.car-btn.left{left: -10px}
+.car-btn.right{right: -10px}
+.car-btn svg{width:18px; height:18px}
+
+/* Tools */
+.tools-grid{display:grid; grid-template-columns: 1.1fr .9fr; gap: 18px}
+.tool-hero{padding: 18px; border-radius: 24px; background: linear-gradient(180deg, color-mix(in oklab, var(--surface) 92%, white), color-mix(in oklab, var(--teal-1) 55%, white))}
+.tool-hero h3{margin:0; font-size:1.18rem; letter-spacing:-.35px}
+.tool-hero p{margin:10px 0 0 0; color:var(--muted); line-height:1.55}
+.tool-list{display:grid; grid-template-columns: 1fr; gap: 10px; margin-top: 14px}
+.tool{
+  display:flex; align-items:flex-start; gap:10px;
+  padding: 12px;
+  border-radius: 18px;
+  border:1px solid color-mix(in oklab, var(--border) 82%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  transition: transform 140ms ease, box-shadow 180ms ease;
+}
+.tool:hover{transform: translateY(-1px); box-shadow: var(--shadow-sm); text-decoration:none}
+.tool svg{width:18px; height:18px; margin-top:2px; color: color-mix(in oklab, var(--teal-5) 82%, var(--text))}
+.tool b{display:block}
+.tool span{display:block; color:var(--muted); font-size:.92rem; line-height:1.35; margin-top:3px}
+
+/* Recommended reads tabs */
+.tabs{display:flex; gap:8px; flex-wrap:wrap}
+.tab{
+  border-radius: 999px;
+  padding: .55rem .8rem;
+  border: 1px solid color-mix(in oklab, var(--border) 82%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  font-weight:750;
+  color: color-mix(in oklab, var(--text) 86%, var(--teal-5));
+  cursor:pointer;
+  transition: background 160ms ease, transform 140ms ease, box-shadow 180ms ease;
+}
+.tab:hover{box-shadow: var(--shadow-sm)}
+.tab[aria-selected="true"]{background: linear-gradient(180deg, color-mix(in oklab, var(--teal-2) 55%, white), color-mix(in oklab, var(--surface) 82%, var(--teal-1))); border-color: color-mix(in oklab, var(--border) 72%, var(--teal-2))}
+
+.grid{display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-top: 14px}
+.article{padding: 14px; border-radius: 22px; transition: transform 140ms ease, box-shadow 180ms ease}
+.article:hover{transform: translateY(-2px); box-shadow: var(--shadow-sm); text-decoration:none}
+.article .tag{font-size:.74rem; font-weight:850; letter-spacing:.08em; text-transform:uppercase; color: color-mix(in oklab, var(--teal-5) 82%, var(--text))}
+.article h3{margin:10px 0 0 0; font-size:1.05rem; letter-spacing:-.25px; line-height:1.25}
+.article p{margin:8px 0 0 0; color:var(--muted); line-height:1.45; font-size:.95rem}
+.article .by{margin-top:10px; display:flex; align-items:center; justify-content:space-between; color:var(--muted); font-size:.9rem}
+.dot{width:6px; height:6px; border-radius:999px; background: color-mix(in oklab, var(--accent) 80%, var(--teal-4))}
+
+/* Trust pillars */
+.trust{padding: 22px}
+.pillars{display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 14px}
+.pillar{padding: 14px; border-radius: 22px; border:1px solid color-mix(in oklab, var(--border) 82%, white); background: color-mix(in oklab, var(--surface) 92%, white)}
+.pillar h3{margin:0; font-size:1.0rem; letter-spacing:-.25px}
+.pillar p{margin:8px 0 0 0; color:var(--muted); line-height:1.45}
+
+/* Programs & videos */
+.cards4{display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-top: 14px}
