+              linear-gradient(180deg, color-mix(in oklab, var(--teal-2) 55%, white), color-mix(in oklab, var(--surface) 75%, var(--teal-1)));
+  display:flex; align-items:center; justify-content:center;
+  box-shadow: 0 1px 0 rgba(0,0,0,.03);
+}
+.topic .img svg{width:34px; height:34px; color: color-mix(in oklab, var(--teal-5) 86%, var(--text))}
+.topic h4{margin:12px 0 0 0; font-size:1.0rem; letter-spacing:-.25px}
+.topic p{margin:6px 0 0 0; color:var(--muted); font-size:.9rem; line-height:1.35}
+
+.car-btn{
+  position:absolute;
+  top: 50%;
+  transform: translateY(-50%);
+  width: 44px; height: 44px;
+  border-radius: 999px;
+  border:1px solid color-mix(in oklab, var(--border) 76%, white);
+  background: color-mix(in oklab, var(--surface) 90%, white);
+  box-shadow: 0 10px 25px rgba(2,20,24,.12);
+  display:flex; align-items:center; justify-content:center;
+  cursor:pointer;
+  transition: transform 140ms ease, box-shadow 180ms ease;
+}
+.car-btn:hover{box-shadow: var(--shadow-md)}
+.car-btn:active{transform: translateY(-50%) scale(.98)}
+.car-btn.left{left: -10px}
+.car-btn.right{right: -10px}
+.car-btn svg{width:18px; height:18px}
+
+/* Tools */
+.tools-grid{display:grid; grid-template-columns: 1.1fr .9fr; gap: 18px}
+.tool-hero{padding: 18px; border-radius: 24px; background: linear-gradient(180deg, color-mix(in oklab, var(--surface) 92%, white), color-mix(in oklab, var(--teal-1) 55%, white))}
+.tool-hero h3{margin:0; font-size:1.18rem; letter-spacing:-.35px}
+.tool-hero p{margin:10px 0 0 0; color:var(--muted); line-height:1.55}
+.tool-list{display:grid; grid-template-columns: 1fr; gap: 10px; margin-top: 14px}
+.tool{
+  display:flex; align-items:flex-start; gap:10px;
+  padding: 12px;
+  border-radius: 18px;
+  border:1px solid color-mix(in oklab, var(--border) 82%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  transition: transform 140ms ease, box-shadow 180ms ease;
+}
+.tool:hover{transform: translateY(-1px); box-shadow: var(--shadow-sm); text-decoration:none}
+.tool svg{width:18px; height:18px; margin-top:2px; color: color-mix(in oklab, var(--teal-5) 82%, var(--text))}
+.tool b{display:block}
+.tool span{display:block; color:var(--muted); font-size:.92rem; line-height:1.35; margin-top:3px}
+
+/* Recommended reads tabs */
+.tabs{display:flex; gap:8px; flex-wrap:wrap}
+.tab{
+  border-radius: 999px;
+  padding: .55rem .8rem;
+  border: 1px solid color-mix(in oklab, var(--border) 82%, white);
+  background: color-mix(in oklab, var(--surface) 92%, white);
+  font-weight:750;
+  color: color-mix(in oklab, var(--text) 86%, var(--teal-5));
+  cursor:pointer;
+  transition: background 160ms ease, transform 140ms ease, box-shadow 180ms ease;
+}
+.tab:hover{box-shadow: var(--shadow-sm)}
+.tab[aria-selected="true"]{background: linear-gradient(180deg, color-mix(in oklab, var(--teal-2) 55%, white), color-mix(in oklab, var(--surface) 82%, var(--teal-1))); border-color: color-mix(in oklab, var(--border) 72%, var(--teal-2))}
+
+.grid{display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-top: 14px}
+.article{padding: 14px; border-radius: 22px; transition: transform 140ms ease, box-shadow 180ms ease}
+.article:hover{transform: translateY(-2px); box-shadow: var(--shadow-sm); text-decoration:none}
+.article .tag{font-size:.74rem; font-weight:850; letter-spacing:.08em; text-transform:uppercase; color: color-mix(in oklab, var(--teal-5) 82%, var(--text))}
+.article h3{margin:10px 0 0 0; font-size:1.05rem; letter-spacing:-.25px; line-height:1.25}
+.article p{margin:8px 0 0 0; color:var(--muted); line-height:1.45; font-size:.95rem}
+.article .by{margin-top:10px; display:flex; align-items:center; justify-content:space-between; color:var(--muted); font-size:.9rem}
+.dot{width:6px; height:6px; border-radius:999px; background: color-mix(in oklab, var(--accent) 80%, var(--teal-4))}
+
+/* Trust pillars */
+.trust{padding: 22px}
+.pillars{display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; margin-top: 14px}
+.pillar{padding: 14px; border-radius: 22px; border:1px solid color-mix(in oklab, var(--border) 82%, white); background: color-mix(in oklab, var(--surface) 92%, white)}
+.pillar h3{margin:0; font-size:1.0rem; letter-spacing:-.25px}
+.pillar p{margin:8px 0 0 0; color:var(--muted); line-height:1.45}
+
+/* Programs & videos */
+.cards4{display:grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-top: 14px}
+.program{padding: 14px; border-radius: 22px}
+.program h3{margin:10px 0 0 0; font-size:1.0rem; letter-spacing:-.25px}
+.program p{margin:8px 0 0 0; color:var(--muted); line-height:1.45; font-size:.95rem}
+
+.video{
+  padding: 14px;
+  border-radius: 22px;
+}
+.video-thumb{
+  border-radius: 18px;
+  border: 1px solid color-mix(in oklab, var(--border) 78%, white);
+  min-height: 140px;
+  background: radial-gradient(300px 180px at 10% 10%, color-mix(in oklab, var(--teal-2) 55%, white) 0%, transparent 60%),
+              radial-gradient(260px 160px at 95% 20%, color-mix(in oklab, var(--accent-2) 35%, white) 0%, transparent 55%),
+              linear-gradient(180deg, color-mix(in oklab, var(--surface) 88%, white), color-mix(in oklab, var(--surface-2) 80%, var(--teal-1)));
+  display:flex; align-items:center; justify-content:center;
+  box-shadow: 0 1px 0 rgba(0,0,0,.03);
+}
+.play{
+  width: 56px; height: 56px; border-radius:999px;
+  border: 1px solid color-mix(in oklab, var(--border) 70%, white);
+  background: rgba(255,255,255,.85);
+  display:flex; align-items:center; justify-content:center;
+  box-shadow: 0 14px 30px rgba(2,20,24,.14);
+}
+.play svg{width:22px; height:22px; margin-left:2px; color: color-mix(in oklab, var(--teal-5) 85%, var(--text))}
+
+/* Footer */
+footer{padding: 34px 0 46px; border-top: 1px solid color-mix(in oklab, var(--border) 75%, white); background: linear-gradient(180deg, color-mix(in oklab, var(--surface) 92%, white), color-mix(in oklab, var(--teal-1) 38%, white))}
+.footer-grid{display:grid; grid-template-columns: 1.1fr .9fr; gap: 18px; align-items:start}
+.footer-card{padding: 18px; border-radius: 24px}
+.footer-card h3{margin:0; font-size:1.12rem; letter-spacing:-.35px}
+.footer-card p{margin:10px 0 0 0; color:var(--muted); line-height:1.55}
+.footer-links{display:flex; flex-wrap:wrap; gap:10px; margin-top: 14px}
+.footer-links a{color: color-mix(in oklab, var(--text) 80%, var(--teal-5)); font-weight:650; padding:8px 10px; border-radius: 999px}
+.footer-links a:hover{background: color-mix(in oklab, var(--teal-1) 60%, white); text-decoration:none}
+.legal{margin-top: 16px; color: var(--muted); font-size:.9rem; line-height:1.5}
+.social{display:flex; gap:10px; flex-wrap:wrap; margin-top: 12px}
+.social a{display:inline-flex; align-items:center; gap:8px; padding:10px 12px; border-radius: 999px; border:1px solid color-mix(in oklab, var(--border) 78%, white); background: color-mix(in oklab, var(--surface) 92%, white); font-weight:750}
+.social a:hover{box-shadow: var(--shadow-sm); text-decoration:none}
+.social svg{width:16px; height:16px}
+
+/* Mobile */
+.hamburger{display:none}
+.mobile-panel{display:none}
+
+@media (max-width: 980px){
+  .nav{display:none}
+  .hamburger{display:inline-flex}
+  .mega{left: 12px; right: 12px; transform:none; width: auto}
+  .mega-inner{grid-template-columns: 1fr}
+  .mega-right{border-left:none; border-top: 1px solid color-mix(in oklab, var(--border) 75%, white)}
+  .hero-grid{grid-template-columns: 1fr}
+  .trending-grid{grid-template-columns: 1fr}
+  .cta-inner{grid-template-columns: 1fr}
+  .tools-grid{grid-template-columns: 1fr}
+  .grid{grid-template-columns: 1fr}
+  .pillars{grid-template-columns: 1fr 1fr}
+  .cards4{grid-template-columns: 1fr 1fr}
+  .car-btn.left{left: 6px}
+  .car-btn.right{right: 6px}
+  .footer-grid{grid-template-columns: 1fr}
+  .mobile-panel[data-open="true"]{display:block; position:fixed; inset:72px 0 0 0; background: rgba(255,255,255,.92); backdrop-filter: blur(10px); z-index:45; border-top: 1px solid color-mix(in oklab, var(--border) 75%, white)}
+  .mobile-panel .inner{padding: 14px 20px}
+  .mobile-panel .row{display:flex; flex-direction:column; gap:8px}
+  .mobile-panel button{width:100%; justify-content:space-between}
+}
+
+@media (max-width: 520px){
+  .pillars{grid-template-columns: 1fr}
+  .cards4{grid-template-columns: 1fr}
+  .hero h1{font-size:1.75rem}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; transition-duration: 0.001ms !important; scroll-behavior:auto !important}
+}
+
*** End Patch
PATCH"}

